// UpdateDetails implements the project-owned lead.update_details Handler.
func UpdateDetails(ctx context.Context, caps capabilities.UpdateDetailsCapabilities, input capabilities.UpdateDetailsInput) (capabilities.UpdateDetailsOutput, error) {
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.UpdateDetailsOutput{}, err
	}
	if lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return capabilities.UpdateDetailsOutput{}, businessError("lead.update_details.forbidden", "only the lead owner may update lead details")
	}

	mutation := data.NewLeadUpdate(lead.ID).
		RequireOwnerUserEqual(principal.UserID, "lead.update_details.owner_changed").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	if input.ContactName != nil {
		mutation = mutation.SetContactName(*input.ContactName)
	}
	if input.ExpectedAmount != nil {
		mutation = mutation.SetExpectedAmount(*input.ExpectedAmount)
	}
	if input.Phone != nil {
		mutation = mutation.SetPhone(*input.Phone)
	}
	if input.Source != nil {
		mutation = mutation.SetSource(schema.LeadSource(*input.Source))
	}
	updated, err := caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.UpdateDetailsOutput{}, err
	}
	if _, err = caps.LeadActivity.Create(ctx, schema.CreateLeadActivity{
		ActorUser: principal.UserID,
		EventType: schema.LeadActivityEventTypeDetailsUpdated,
		LeadID: schema.NewLeadActivityLeadIDReference(lead.ID),
		OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.UpdateDetailsOutput{}, err
	}
	return capabilities.UpdateDetailsOutput{LeadID: string(updated.ID), Status: string(updated.Status)}, nil
}

func businessError(code, message string) error {
	return &capabilities.BusinessError{Code: code, Message: message}
}
