// Advance implements the project-owned lead.advance Handler.
func Advance(ctx context.Context, caps capabilities.AdvanceCapabilities, input capabilities.AdvanceInput) (capabilities.AdvanceOutput, error) {
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	if lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return capabilities.AdvanceOutput{}, businessError("lead.advance.forbidden", "only the lead owner may advance the lead")
	}
	target := schema.LeadStatus(input.Status)
	if !legalLeadAdvance(lead.Status, target) {
		return capabilities.AdvanceOutput{}, businessError("lead.advance.invalid_transition", "the requested lead transition is not allowed")
	}
	now := time.Now().UTC()
	updated, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
		SetStatus(target).
		SetStatusChangedAt(now).
		RequireOwnerUserEqual(principal.UserID, "lead.advance.owner_changed").
		RequireStatusEqual(lead.Status, "lead.advance.status_changed").
		WithExpectedUpdatedAt(lead.UpdatedAt))
	if err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	fromStatus, toStatus := string(lead.Status), string(target)
	if _, err = caps.LeadActivity.Create(ctx, schema.CreateLeadActivity{
		ActorUser: principal.UserID,
		EventType: schema.LeadActivityEventTypeStatusChanged,
		FromStatus: &fromStatus,
		LeadID: schema.NewLeadActivityLeadIDReference(lead.ID),
		OccurredAt: now,
		ToStatus: &toStatus,
	}); err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	return capabilities.AdvanceOutput{LeadID: string(updated.ID), Status: string(updated.Status)}, nil
}

func legalLeadAdvance(from, to schema.LeadStatus) bool {
	return (from == schema.LeadStatusNew && to == schema.LeadStatusContacted) ||
		(from == schema.LeadStatusContacted && to == schema.LeadStatusQualified) ||
		(from == schema.LeadStatusQualified && to == schema.LeadStatusLost)
}
