def command_finding(args, project: Path, session: str) -> int:
    if args.status not in {"open", "resolved", "accepted_limitation"}:
        raise GateError("unsupported finding status")
    if args.status != "resolved" and not args.note.strip():
        raise GateError("open and accepted limitation findings require a note")
    state = sync_gates(project, session, load_state(project, session))
    evidence = [evidence_item(project, value) for value in args.evidence_path]
    if args.status in {"resolved", "accepted_limitation"} and not evidence:
        raise GateError(f"{args.status} finding requires evidence")
    state["findings"][args.finding_id] = {
        "finding_id": args.finding_id,
        "stage": args.stage,
        "status": args.status,
        "note": args.note.strip(),
        "evidence": evidence,
        "source_sha": identities(project)["source_sha"],
        "blueprint_sha": identities(project)["blueprint_sha"],
        "runtime_manifest_sha": identities(project)["runtime_manifest_sha"],
        "verified_at": now(),
    }
