    print(json.dumps(state["findings"][args.finding_id], ensure_ascii=False, separators=(",", ":")))
    return 0


def gate_recovery_detail(project: Path, gate: dict, effective: str, current: dict) -> tuple[list[str], dict]:
    invalidated_inputs = []
    action = {
        "gate_id": gate["gate_id"], "gate_key": gate.get("gate_key", gate["gate_id"]),
        "generation": gate.get("generation", 1), "stage": gate.get("stage", ""),
    }
    for binding in gate.get("bindings", []):
        key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
        if gate.get(key) != current.get(key):
            invalidated_inputs.append(binding)
    if effective in {"failed", "stale"} and gate.get("evidence_type") == "command_receipt":
        try:
            receipt, item = attached_command_receipt(project, gate)
            argv = receipt.get("argv", receipt.get("command", []))
            if isinstance(argv, list) and argv and all(isinstance(value, str) for value in argv):
                try:
                    _, replay_cwd = current_replay_cwd(
                        project, receipt.get("cwd", "."),
                    )
                except GateError as error:
                    invalidated_inputs.append("current_replay_cwd")
                    action.update({
                        "action": "repair_current_replay_owner",
                        "owner": "command_owner",
                        "reason_code": "missing_current_replay_owner",
                        "source_receipt": item["path"],
                        "diagnosis": str(error),
                    })
                else:
                    action.update({
                        "action": "create_next_generation_and_run",
                        "command_argv": argv,
                        "cwd": replay_cwd,
                        "bindings": receipt.get("bindings", gate.get("bindings", [])),
                        "source_receipt": item["path"],
                        "next_gate_metadata": {
                            "gate_key": gate.get("gate_key", gate["gate_id"]),
                            "generation": gate.get("generation", 1) + 1,
                            "supersedes": gate["gate_id"],
                        },
                    })
                if effective == "failed":
                    error = receipt.get("expectation", {}).get("error", "")
                    if error:
                        action["failure"] = str(error)[:MAX_FAILURE_REASON_CHARS]
        except (GateError, OSError, json.JSONDecodeError) as error:
            invalidated_inputs.append("attached_evidence")
            action.update({"action": "repair_evidence_contract", "diagnosis": str(error)})
    elif effective == "pending":
        action["action"] = "complete_current_gate"
    elif effective == "accepted_limitation":
        action["action"] = "resolve_current_limitation"
    else:
        action["action"] = "refresh_current_gate_evidence"
    return sorted(set(invalidated_inputs)), action


