def normalized_runtime_profile_todo(content: str) -> str:
    lines = content.splitlines()
    starts = [index for index, line in enumerate(lines) if line == PROJECTION_START]
    ends = [index for index, line in enumerate(lines) if line == PROJECTION_END]
    if starts or ends:
        if len(starts) != 1 or len(ends) != 1 or starts[0] >= ends[0]:
            raise GateError("Runtime Gate profile TODO projection is unsafe")
        lines[starts[0]:ends[0] + 1] = []
    normalized = []
    blank = False
    for line in lines:
        checkbox = CHECKBOX.match(line)
        if checkbox:
            line = checkbox.group(1) + " " + checkbox.group(3) + checkbox.group(4)
        evidence = EVIDENCE_LINE.match(line)
        if evidence:
            line = evidence.group(1) + "pending"
        if not line.strip():
            if blank:
                continue
            blank = True
            normalized.append("")
        else:
            blank = False
            normalized.append(line)
    return "\n".join(normalized).strip() + "\n"


