def command_receipt_for_migration(
    project: Path, gate: dict, item: dict, current: dict, runtime: dict,
) -> dict:
    validate_artifact_reference(project, item, "Gate command receipt")
    document = command_receipt_document(project, item)
    validate_historical_command_envelope(document)
    receipt_bindings = document.get("bindings")
    receipt_identity = document.get("identity")
    if (
        document.get("contract_version") != COMMAND_RECEIPT_VERSION
        or document.get("gate_id") != gate.get("gate_id")
        or not isinstance(receipt_bindings, list)
        or sorted(receipt_bindings) != sorted(gate.get("bindings", []))
        or not isinstance(receipt_identity, dict)
    ):
        raise GateError("legacy Gate command receipt contract is incomplete")
    for binding in receipt_bindings:
        key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
        if receipt_identity.get(key) != gate.get(key):
            raise GateError("legacy Gate and command receipt binding identities differ")
        if binding != "runtime_cohort" and receipt_identity.get(key) != current.get(key):
            raise GateError(f"legacy Gate has non-cohort identity drift: {binding}")
    proof = document.get("proof", {})
    if not isinstance(proof, dict):
        raise GateError("legacy Gate command receipt proof is invalid")
    for key, artifact in proof.items():
        if not isinstance(artifact, dict) or not artifact.get("path"):
            continue
        validate_historical_artifact_identity(artifact, f"legacy command proof {key}")
    managed = proof.get("managed_runtime")
    if isinstance(managed, dict):
        stable_pairs = {
            "bundle_manifest_sha256": "bundle_manifest_sha256",
            "package_receipt_sha256": "package_receipt_sha256",
            "verification_receipt_sha256": "verification_receipt_sha256",
            "finalization_receipt_sha256": "finalization_receipt_sha256",
            "project_source_tree_sha256": "project_source_tree_sha256",
            "runtime_manifest_sha256": "runtime_manifest_sha256",
            "binary_sha256": "binary_sha256",
            "database_driver": "database_driver",
            "database_identity_sha256": "database_identity_sha256",
        }
        if (
            managed.get("contract_version") != MANAGED_RUNTIME_CONTRACT
            or managed.get("state") != "running"
            or managed.get("cohort_state") != "current"
            or managed.get("healthy") is not True
            or any(managed.get(left) != runtime.get(right) for left, right in stable_pairs.items())
        ):
            raise GateError("legacy managed Runtime proof differs from the stable current cohort")
    return document


def command_operation_family(document: dict) -> str:
    """Derive a stable operation family from receipt argv, never Gate prose.

    The executable and leading positional operation tokens are enough to bind
    legacy lineage without embedding project paths, option values, or labels.
    Exact argv/cwd remains preserved and validated by the receipt itself.
    """
    argv = document.get("argv", document.get("command"))
    if not isinstance(argv, list) or not argv:
        raise GateError("legacy command receipt argv is invalid")
    executable = Path(argv[0]).name.lower()
    positional = []
    skip_value = False
    for token in argv[1:]:
        if skip_value:
            skip_value = False
            continue
        if token.startswith("--"):
            skip_value = "=" not in token
            continue
        if token.startswith("-") or os.path.isabs(token):
            continue
        positional.append(token.lower())
        if len(positional) == 3:
            break
    return ":".join([executable, *positional])


def legacy_migration_anchor(
    project: Path, state: dict, current: dict, closure: dict,
) -> tuple[str, list[dict]]:
    anchors: list[dict] = []
    cohorts = set()
    for gate in state["gates"].values():
        if (
            not gate.get("active", True)
            or gate.get("status") != "passed"
            or gate.get("evidence_type") != "command_receipt"
            or "runtime_cohort" not in gate.get("bindings", [])
        ):
            continue
        for item in gate.get("evidence", []):
            document = command_receipt_for_migration(
                project, gate, item, current, closure["runtime"],
            )
            managed = document.get("proof", {}).get("managed_runtime")
            if not isinstance(managed, dict):
                continue
            legacy_sha = legacy_runtime_cohort_sha(project, managed.get("sha256", ""))
            if not legacy_sha or legacy_sha != gate.get("runtime_cohort_sha"):
                raise GateError("legacy process receipt does not derive the declared cohort identity")
            cohorts.add(legacy_sha)
            anchors.append({
                "gate_id": gate["gate_id"], "command_receipt": item,
                "managed_runtime_receipt_sha256": managed["sha256"],
            })
    if len(cohorts) != 1 or not anchors:
        raise GateError("one strict legacy process/cohort anchor could not be proven")
    return next(iter(cohorts)), anchors


def gate_legacy_migration_reason(
    project: Path, gate: dict, current: dict, closure: dict, legacy_cohort: str,
) -> str:
    if gate.get("status") != "passed":
        return "declared Gate status was not passed"
    if "runtime_cohort" not in gate.get("bindings", []):
        return "Gate does not carry a legacy runtime_cohort binding"
    if "runtime_instance" in gate.get("bindings", []):
        return "PID-sensitive runtime_instance evidence cannot be cohort-migrated"
    if gate.get("runtime_cohort_sha") != legacy_cohort:
        return "Gate runtime_cohort does not match the proven legacy cohort"
    if not gate.get("evidence"):
        return "Gate has no attached evidence"
    for binding in gate.get("bindings", []):
        if binding == "runtime_cohort":
            continue
        key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
        if not gate.get(key) or gate.get(key) != current.get(key):
            return f"Gate has non-cohort identity drift: {binding}"
    try:
        if gate.get("evidence_type") == "command_receipt":
            for item in gate["evidence"]:
                command_receipt_for_migration(
                    project, gate, item, current, closure["runtime"],
                )
        else:
            for item in gate["evidence"]:
                validate_artifact_reference(project, item, "legacy Gate evidence")
            if gate.get("evidence_type") == "cli_receipt":
                for item in gate["evidence"]:
                    validate_receipt(project, item, "cli_receipt", gate, gate.get("bindings", []))
    except (GateError, OSError, json.JSONDecodeError) as error:
        return str(error)
    return ""


