def command_run_locked(args, project: Path, session: str) -> int:
    if not args.command:
        raise GateError("run requires a command after --")
    bindings = sorted(set(args.bind))
    if not bindings or any(value not in BINDINGS for value in bindings):
        raise GateError("run requires valid identity bindings")
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    if gate.get("kind") in ALL_MACHINE_GATE_KINDS and not getattr(args, "profile_owned", False):
        raise GateError("machine-owned profile Gates may execute only through their profile runner")
    requirements_only = requirements_only_scope(project, session)
    if requirements_only:
        validate_requirements_database_contract(project)
    identity_before = identities(project)
    if not requirements_only and REQUIREMENT_COVERAGE_MARKER in gate["label"].lower():
        raise GateError("implementation requirement coverage is CLI-owned by reconcile")
    if gate.get("pid_sensitive"):
        bindings = sorted(set(bindings) | {"runtime_instance"})
    if REQUIREMENT_COVERAGE_MARKER in gate["label"].lower():
        required_binding = "requirements" if requirements_only else "source"
        if required_binding not in bindings:
            raise GateError(
                f"all requirements checkpoint must bind the current {required_binding} identity"
            )
    validate_gate_dependencies(project, state, gate)
    validate_safe_argv(args.command)
    kind = validate_command_for_gate(gate, args.command, project)
    if kind in {"project_verify", "project_package"}:
        # Both commands consume the exact current delivery Runtime manifest.
        # Make that dependency mandatory even if a caller supplies only a
        # source binding.
        bindings = sorted(set(bindings) | {"runtime"})
    elif kind in {"runtime_start", "runtime_status"}:
        # Managed Runtime evidence is meaningful only for the current source
        # and exact live process/database cohort. Callers cannot omit either.
        bindings = sorted(set(bindings) | {
            "source", "runtime", "runtime_cohort", "runtime_instance",
        })
        identity_before["runtime_manifest_sha"] = delivery_runtime_manifest_sha(project)
    before_bindings = [
        value for value in bindings
        if not (
            (kind == "runtime_start" and value in {"runtime_cohort", "runtime_instance"})
            or (kind in {"project_verify", "project_package"} and value == "runtime")
        )
    ]
    require_available_bindings(identity_before, before_bindings)
    execution_cwd, receipt_cwd = command_cwd(project, args.cwd)
    if args.expect_exit != 0 and (
        kind != "project_check"
        or "diagnostic inventory" not in gate["label"].lower()
    ):
        raise GateError("nonzero expectation is limited to an explicit project-check diagnostic inventory Gate")
    if kind == "project_check":
        if (
            args.expect_exit == 0
            and not args.expect_json_contract
            and not args.expect_json_state
            and not args.expect_json_diagnostic_code
        ):
            # Compatibility for the original successful `run -- <project check>`
            # call: its only valid meaning is the strict exit-0/valid contract.
            args.expect_json_contract = PROJECT_CHECK_CONTRACT
            args.expect_json_state = "valid"
