def option_value(command: list[str], name: str) -> str:
    for index, value in enumerate(command):
        if value == name and index + 1 < len(command):
            return command[index + 1]
        if value.startswith(name + "="):
            return value.split("=", 1)[1]
    return ""


def domainry_command(command: list[str], family: tuple[str, ...], project: Path) -> bool:
    if len(command) < len(family) + 1 or Path(command[0]).name not in {"domainry-cli", "domainry-cli.exe"}:
        return False
    if tuple(command[1:1 + len(family)]) != family or "--json" not in command:
        return False
    raw_project = option_value(command, "--project")
    if not raw_project:
        return False
    try:
        return Path(raw_project).expanduser().resolve() == project
    except OSError:
        return False


def lexical_historical_path(project: Path, raw_path: str, cwd: str, *, from_project: bool) -> Path:
    """Normalize a recorded path without reopening its historical cwd."""
    if (
        not isinstance(raw_path, str) or not raw_path or "\x00" in raw_path
        or not isinstance(cwd, str) or not cwd or "\x00" in cwd
    ):
        raise GateError("historical command path is invalid")
    candidate = Path(raw_path).expanduser()
    if candidate.is_absolute():
        combined = candidate
    elif from_project:
        combined = project / candidate
    else:
        recorded_cwd = Path(cwd).expanduser()
        base = recorded_cwd if recorded_cwd.is_absolute() else project / recorded_cwd
        combined = base / candidate
    normalized = Path(os.path.normpath(str(combined)))
    if not normalized.is_absolute():
        raise GateError("historical command path is not absolute after normalization")
    if project != normalized and project not in normalized.parents:
        raise GateError("historical command path must remain inside the project")
    return normalized


