#!/usr/bin/env python3
"""Live CRM conversion canary; emits only non-secret semantic observations."""

import hashlib
import importlib.util
import json
import os
import secrets


PROJECT_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
CORE_PATH = "/Users/tiger/.codex/skills/domainry-builder-v1/assets/acceptance-harness-core.py"


def load_core():
    spec = importlib.util.spec_from_file_location("domainry_acceptance_core", CORE_PATH)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def canonical_hash(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def rotate_session(core, runtime, user_id):
    login = runtime.request("POST", "/auth/login", body={
        "workspace_id": "default", "login": user_id, "password": core.DEV_DEFAULT_PASSWORD,
    })
    if login.status != 200 or not (login.body or {}).get("access_token"):
        raise core.HarnessError("formal canary login failed for %s" % user_id)
    base = {
        "user_id": user_id,
        "token": login.body["access_token"],
        "workspace_id": login.body.get("workspace_id") or "default",
    }
    rotated = "Can!" + secrets.token_hex(12)
    changed = runtime.request(
        "POST", "/auth/change-password", session=base,
        idempotency_key=core.new_probe_token("canary-password"),
        body={"current_password": core.DEV_DEFAULT_PASSWORD, "new_password": rotated},
    )
    if changed.status != 200 or not (changed.body or {}).get("access_token"):
        raise core.HarnessError("formal canary password handoff failed for %s" % user_id)
    session = {
        "user_id": user_id,
        "token": changed.body["access_token"],
        "workspace_id": changed.body.get("workspace_id") or "default",
    }
    principal = runtime.principal_context(session)
    matches = []
    for candidate in principal.get("request_contexts") or []:
        headers = candidate.get("canonical_request_headers") or {}
        if headers.get("X-Surface-Key") == "business_workspace":
            matches.append(candidate)
    if len(matches) != 1:
        raise core.HarnessError("formal business principal context is not unique for %s" % user_id)
    contextual = dict(session)
    contextual["request_headers"] = dict(matches[0]["canonical_request_headers"])
    return contextual, rotated


def restore_default(core, runtime, session, rotated):
    restored = runtime.request(
        "POST", "/auth/change-password", session=session,
        idempotency_key=core.new_probe_token("canary-password-restore"),
        body={"current_password": rotated, "new_password": core.DEV_DEFAULT_PASSWORD},
    )
    if restored.status != 200:
        raise core.HarnessError("formal canary credential restoration failed")


def record_data(exchange):
    if exchange.status != 200 or not exchange.body:
        return None
    return exchange.body.get("data") if "data" in exchange.body else exchange.body


def main():
    core = load_core()
    state = core.load_json(os.path.join(PROJECT_ROOT, core.RUNTIME_STATE_RELATIVE))
    runtime = core.Runtime(state["api_base_url"])
    sessions = []
    try:
        east, east_password = rotate_session(core, runtime, "east_rep_user")
        sessions.append((east, east_password))
        director, director_password = rotate_session(core, runtime, "sales_director_user")
        sessions.append((director, director_password))

        listed = runtime.request("GET", "/objects/lead/records?page=1&page_size=100", session=east)
        core.ReasonOracle.success(listed, require_non_empty=True)
        items = (listed.body or {}).get("items") or []
        target = next((item for item in items if (item.get("data") or {}).get("company_name") == "East Small Co"), None)
        if not target or not target.get("id"):
            raise core.HarnessError("canary target lead is absent")
        lead_id = target["id"]
        request_key = core.new_probe_token("canary-direct-conversion")
        converted = runtime.request(
            "POST", "/objects/lead/records/%s/actions/lead.request_conversion" % lead_id,
            session=east, idempotency_key=request_key,
            body={"data": {"request_key": request_key}},
        )
        core.ReasonOracle.success(converted, require_non_empty=True)
        result = (converted.body or {}).get("result") or (converted.body or {}).get("data") or converted.body or {}
        customer_id = result.get("customer_id")
        if not customer_id:
            raise core.HarnessError("conversion returned no customer identity")

        lead_read = runtime.request("GET", "/objects/lead/records/%s" % lead_id, session=east)
        core.ReasonOracle.success(lead_read, require_non_empty=True)
        lead_data = record_data(lead_read) or {}
        if lead_data.get("status") != "converted":
            raise core.HarnessError("converted lead did not persist terminal status")
        customer_read = runtime.request("GET", "/objects/customer/records/%s" % customer_id, session=east)
        core.ReasonOracle.success(customer_read, require_non_empty=True)
        customer_data = record_data(customer_read) or {}
        if customer_data.get("source_lead_id") != lead_id:
            raise core.HarnessError("customer read-back is not linked to the converted lead")

        before = canonical_hash(lead_read.body)
        denied_key = core.new_probe_token("canary-denied-conversion")
        denied = runtime.request(
            "POST", "/objects/lead/records/%s/actions/lead.request_conversion" % lead_id,
            session=director, idempotency_key=denied_key,
            body={"data": {"request_key": denied_key}},
        )
        after_read = runtime.request("GET", "/objects/lead/records/%s" % lead_id, session=director)
        core.ReasonOracle.success(after_read, require_non_empty=True)
        core.ReasonOracle.rejection(
            denied, statuses=(403,), error_code="backend.action.permission_denied",
            before_sha256=before, after_sha256=canonical_hash(after_read.body),
        )
        print(json.dumps({
            "state": "passed", "canary": "direct_conversion_atomicity_and_denial",
            "lead_id": lead_id, "customer_id": customer_id,
            "lead_status": "converted", "denied_status": denied.status,
            "denied_error_code": denied.error_code, "unchanged_denied_state": True,
        }, sort_keys=True))
    finally:
        for session, rotated in reversed(sessions):
            restore_default(core, runtime, session, rotated)


if __name__ == "__main__":
    main()
