package crm

import (
	"context"
	capabilities "example.com/domainry/m1crm/generated/capabilities"
	"example.com/domainry/m1crm/generated/data"
	"example.com/domainry/m1crm/generated/schema"
	"math/big"
	"time"
)

// RequestConversion implements the project-owned lead.request_conversion Handler.
func RequestConversion(ctx context.Context, caps capabilities.RequestConversionCapabilities, input capabilities.RequestConversionInput) (capabilities.RequestConversionOutput, error) {
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return capabilities.RequestConversionOutput{}, businessError("lead.request_conversion.forbidden", "only the lead owner may request conversion")
	}
	if lead.Status != schema.LeadStatusQualified {
		return capabilities.RequestConversionOutput{}, businessError("lead.request_conversion.not_qualified", "only a qualified lead may be converted")
	}
	amount, ok := new(big.Rat).SetString(string(lead.ExpectedAmount))
	if !ok {
		return capabilities.RequestConversionOutput{}, businessError("lead.request_conversion.invalid_amount", "lead amount is not an exact decimal")
	}
	threshold := new(big.Rat).SetInt64(100000)
	now := time.Now().UTC()
	if amount.Cmp(threshold) < 0 {
		exists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereSourceLeadIDEqual(schema.NewCustomerSourceLeadIDReference(lead.ID)))
		if err != nil {
			return capabilities.RequestConversionOutput{}, err
		}
		if exists {
			return capabilities.RequestConversionOutput{}, businessError("lead.request_conversion.customer_exists", "a customer already exists for this lead")
		}
		customer, err := caps.Customer.Create(ctx, customerFromLead(lead))
		if err != nil {
			return capabilities.RequestConversionOutput{}, err
		}
		updated, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
			SetStatus(schema.LeadStatusConverted).
			SetStatusChangedAt(now).
			RequireOwnerUserEqual(principal.UserID, "lead.request_conversion.owner_changed").
			RequireStatusEqual(schema.LeadStatusQualified, "lead.request_conversion.status_changed").
			WithExpectedUpdatedAt(lead.UpdatedAt))
		if err != nil {
			return capabilities.RequestConversionOutput{}, err
		}
		fromStatus, toStatus := string(lead.Status), string(schema.LeadStatusConverted)
		if _, err = caps.LeadActivity.Create(ctx, schema.CreateLeadActivity{
			ActorUser: principal.UserID, EventType: schema.LeadActivityEventTypeConversionApproved,
			FromStatus: &fromStatus, LeadID: schema.NewLeadActivityLeadIDReference(lead.ID),
			OccurredAt: now, ToStatus: &toStatus,
		}); err != nil {
			return capabilities.RequestConversionOutput{}, err
		}
		customerID := string(customer.ID)
		return capabilities.RequestConversionOutput{CustomerID: &customerID, LeadID: string(updated.ID), Status: string(updated.Status)}, nil
	}

	pending, err := caps.ConversionApproval.Exists(ctx, data.NewConversionApprovalQuery().
		WhereLeadIDEqual(schema.NewConversionApprovalLeadIDReference(lead.ID)).
		WhereStatusEqual(schema.ConversionApprovalStatusPending))
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if pending {
		return capabilities.RequestConversionOutput{}, businessError("lead.request_conversion.pending_exists", "a pending conversion approval already exists")
	}
	approval, err := caps.ConversionApproval.Create(ctx, schema.CreateConversionApproval{
		AmountSnapshot:    schema.ConversionApprovalAmountSnapshot(lead.ExpectedAmount),
		LeadID:            schema.NewConversionApprovalLeadIDReference(lead.ID),
		RequestKey:        input.RequestKey,
		RequestedAt:       now,
		RequesterUser:     principal.UserID,
		Status:            schema.ConversionApprovalStatusPending,
		ThresholdSnapshot: schema.ConversionApprovalThresholdSnapshot("100000.00"),
	})
	if err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	if _, err = caps.LeadActivity.Create(ctx, schema.CreateLeadActivity{
		ActorUser: principal.UserID, EventType: schema.LeadActivityEventTypeConversionRequested,
		LeadID: schema.NewLeadActivityLeadIDReference(lead.ID), OccurredAt: now,
	}); err != nil {
		return capabilities.RequestConversionOutput{}, err
	}
	approvalID := string(approval.ID)
	return capabilities.RequestConversionOutput{ApprovalID: &approvalID, LeadID: string(lead.ID), Status: string(approval.Status)}, nil
}

func customerFromLead(lead schema.Lead) schema.CreateCustomer {
	return schema.CreateCustomer{
		Amount: schema.CustomerAmount(lead.ExpectedAmount), CompanyName: lead.CompanyName,
		ContactName: lead.ContactName, Phone: lead.Phone, Source: schema.CustomerSource(lead.Source),
		SourceLeadID: schema.NewCustomerSourceLeadIDReference(lead.ID),
	}
}

