// Prepare implements the project-owned report_export_audit.prepare Handler.
func Prepare(ctx context.Context, caps capabilities.PrepareCapabilities, input capabilities.PrepareInput) (capabilities.PrepareOutput, error) {
	if input.ReportKey != "lead_detail" {
		return capabilities.PrepareOutput{}, businessError("report_export_audit.prepare.unsupported_report", "only the governed lead detail report may be exported")
	}
	exists, err := caps.ReportExportAudit.Exists(ctx, data.NewReportExportAuditQuery().WhereRequestKeyEqual(input.RequestKey))
	if err != nil {
		return capabilities.PrepareOutput{}, err
	}
	if exists {
		return capabilities.PrepareOutput{}, businessError("report_export_audit.prepare.request_exists", "an export audit already exists for this request key")
	}
	audit, err := caps.ReportExportAudit.Create(ctx, schema.CreateReportExportAudit{
		ReportKey:   input.ReportKey,
		RequestKey:  input.RequestKey,
		RequestedBy: caps.Execution.Principal().UserID,
		Status:      schema.ReportExportAuditStatusRequested,
	})
	if err != nil {
		return capabilities.PrepareOutput{}, err
	}
	return capabilities.PrepareOutput{AuditID: string(audit.ID)}, nil
}
