import importlib.util, pathlib, json
root=pathlib.Path('.').resolve(); cp='/Users/tiger/.codex/skills/domainry-builder-v1/assets/acceptance-harness-core.py'
s=importlib.util.spec_from_file_location('c',cp); c=importlib.util.module_from_spec(s); s.loader.exec_module(c)
st=c.load_json(str(root/c.RUNTIME_STATE_RELATIVE)); rt=c.Runtime(st['api_base_url']); ss=c.Sessions(rt,str(root),database_identity_sha256=st.get('database_identity_sha256','')); a=ss.session('admin')
x=rt.request('GET','/operations/scheduler/state',session=a).body or {}
rows=[]
def scan(v,path=''):
  if isinstance(v,dict):
    joined=' '.join(str(q) for q in v.values() if isinstance(q,(str,int,float,bool)))
    if 'weekday_stale_lead_scan' in joined:
      scal={k:q for k,q in v.items() if isinstance(q,(str,int,float,bool,type(None))) and not any(z in k.lower() for z in ('token','password','secret','cookie','dsn'))}
      interesting={k:q for k,q in scal.items() if any(z in k.lower() for z in ('id','status','state','error','attempt','result','output','reason','message','action','workflow','target','definition','time','at'))}
      if interesting: rows.append({'path':path,'values':interesting})
    for k,q in v.items(): scan(q, path+'/'+str(k))
  elif isinstance(v,list):
    for i,q in enumerate(v): scan(q,path+'/'+str(i))
scan(x)
print(json.dumps({'count':len(rows),'tail':rows[-80:]},indent=2))
PY"

