package crm

import (
	"context"
	capabilities "example.com/domainry/m1crm/generated/capabilities"
	"example.com/domainry/m1crm/generated/data"
	"example.com/domainry/m1crm/generated/schema"
	"time"
)

// Decide implements the project-owned conversion_approval.decide Handler.
func Decide(ctx context.Context, caps capabilities.DecideCapabilities, input capabilities.DecideInput) (capabilities.DecideOutput, error) {
	principal := caps.Execution.Principal()
	approval, err := caps.ConversionApproval.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.DecideOutput{}, err
	}
	if approval.Status != schema.ConversionApprovalStatusPending {
		return capabilities.DecideOutput{}, businessError("conversion_approval.decide.not_pending", "only a pending approval may be decided")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, approval.LeadID.ID())
	if err != nil {
		return capabilities.DecideOutput{}, err
	}
	if lead.Status != schema.LeadStatusQualified {
		return capabilities.DecideOutput{}, businessError("conversion_approval.decide.lead_not_qualified", "the approval lead is no longer qualified")
	}
	now := time.Now().UTC()
	decision := schema.ConversionApprovalStatus(input.Decision)
	if decision == schema.ConversionApprovalStatusRejected && (input.RejectionReason == nil || *input.RejectionReason == "") {
		return capabilities.DecideOutput{}, businessError("conversion_approval.decide.rejection_reason_required", "a rejection reason is required")
	}
	if decision != schema.ConversionApprovalStatusApproved && decision != schema.ConversionApprovalStatusRejected {
		return capabilities.DecideOutput{}, businessError("conversion_approval.decide.invalid_decision", "decision must be approved or rejected")
	}
	approvalMutation := data.NewConversionApprovalUpdate(approval.ID).
		SetStatus(decision).
		SetDecidedAt(now).
		RequireStatusEqual(schema.ConversionApprovalStatusPending, "conversion_approval.decide.already_decided").
		WithExpectedUpdatedAt(approval.UpdatedAt)
	if decision == schema.ConversionApprovalStatusRejected {
		approvalMutation = approvalMutation.SetRejectionReason(*input.RejectionReason)
	}
	updatedApproval, err := caps.ConversionApproval.ConditionalUpdate(ctx, approvalMutation)
	if err != nil {
		return capabilities.DecideOutput{}, err
	}

	var customerID *string
	eventType := schema.LeadActivityEventTypeConversionRejected
	notificationType := "crm.conversion_rejected"
	if decision == schema.ConversionApprovalStatusApproved {
		exists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereSourceLeadIDEqual(schema.NewCustomerSourceLeadIDReference(lead.ID)))
		if err != nil {
			return capabilities.DecideOutput{}, err
		}
		if exists {
			return capabilities.DecideOutput{}, businessError("conversion_approval.decide.customer_exists", "a customer already exists for this lead")
		}
		customer, err := caps.Customer.Create(ctx, customerFromLead(lead))
		if err != nil {
			return capabilities.DecideOutput{}, err
		}
		value := string(customer.ID)
		customerID = &value
		if _, err = caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
			SetStatus(schema.LeadStatusConverted).
			SetStatusChangedAt(now).
			RequireStatusEqual(schema.LeadStatusQualified, "conversion_approval.decide.lead_status_changed").
			WithExpectedUpdatedAt(lead.UpdatedAt)); err != nil {
			return capabilities.DecideOutput{}, err
		}
		eventType = schema.LeadActivityEventTypeConversionApproved
		notificationType = "crm.conversion_approved"
	}
	fromStatus := string(lead.Status)
	var toStatus *string
	if decision == schema.ConversionApprovalStatusApproved {
		converted := string(schema.LeadStatusConverted)
		toStatus = &converted
	}
	if _, err = caps.LeadActivity.Create(ctx, schema.CreateLeadActivity{
		ActorUser: principal.UserID, EventType: eventType, FromStatus: &fromStatus,
		LeadID: schema.NewLeadActivityLeadIDReference(lead.ID), OccurredAt: now,
		Reason: input.RejectionReason, ToStatus: toStatus,
	}); err != nil {
		return capabilities.DecideOutput{}, err
	}
	companyName := lead.CompanyName
	if _, err = caps.Notifications.Dispatch(ctx, capabilities.DecideNotificationIntent{
		EventType:        notificationType,
		SourceEventID:    string(approval.ID) + ":" + string(decision),
		RecipientUserIDs: []string{approval.RequesterUser},
		Surface:          "business_workspace",
		SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID),
		SubjectVersion: updatedApproval.UpdatedAt,
		DedupeKey:      string(approval.ID) + ":" + string(decision),
		GroupKey:       string(lead.ID), Alert: true, OccurredAt: now,
		Variables: []capabilities.DecideNotificationVariable{{Key: "company_name", StringValue: &companyName}},
	}); err != nil {
		return capabilities.DecideOutput{}, err
	}
	return capabilities.DecideOutput{ApprovalID: string(updatedApproval.ID), CustomerID: customerID, LeadID: string(lead.ID), Status: string(updatedApproval.Status)}, nil
}

