func TestDecideRejectsPendingApprovalAndNotifiesRequester(t *testing.T) {
	approval := &approvalStub{record: schema.ConversionApproval{ID: "approval-1", UpdatedAt: "approval-v1", LeadID: schema.NewConversionApprovalLeadIDReference("lead-1"), RequesterUser: "east_rep_user", Status: schema.ConversionApprovalStatusPending}}
	lead, activity, notifications := &leadStub{record: ownedLead(schema.LeadStatusQualified, "100000.00")}, &activityStub{}, &decideNotificationStub{}
	reason := "risk review failed"
	out, err := Decide(t.Context(), capabilities.DecideCapabilities{
		Execution:          decideExecutionStub{principal: capabilities.Principal{UserID: "workflow_user"}, target: "approval-1"},
		ConversionApproval: approval, Customer: &customerStub{}, Lead: lead, LeadActivity: activity, Notifications: notifications,
	}, capabilities.DecideInput{Decision: schema.ConversionApprovalDecideDecisionRejected, RejectionReason: &reason, RequestKey: "req-4"})
	if err != nil {
		t.Fatal(err)
	}
	if out.Status != "rejected" || approval.updates != 1 || activity.creates != 1 || notifications.dispatched != 1 || lead.updates != 0 {
		t.Fatalf("unexpected result/effects: %#v", out)
	}
}

