// This file is initial project-owned business source. Domainry will never overwrite it.
package crm

import (
	"context"
	capabilities "example.com/domainry/m1crm/generated/capabilities"
	"example.com/domainry/m1crm/generated/data"
	"example.com/domainry/m1crm/generated/schema"
	"fmt"
	"time"
)

// SendStaleReminders implements the project-owned lead.send_stale_reminders Handler.
func SendStaleReminders(ctx context.Context, caps capabilities.SendStaleRemindersCapabilities, input capabilities.SendStaleRemindersInput) (capabilities.SendStaleRemindersOutput, error) {
	runDate := time.Date(input.RunDate.UTC().Year(), input.RunDate.UTC().Month(), input.RunDate.UTC().Day(), 0, 0, 0, 0, time.UTC)
	cutoff := runDate.AddDate(0, 0, -7)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
		WhereStatusEqual(schema.LeadStatusContacted).
		WhereStatusChangedAtLessThan(cutoff).
		OrderByIDAscending().
		Page(1, 200))
	if err != nil {
		return capabilities.SendStaleRemindersOutput{}, err
	}
	eligible := make([]schema.Lead, 0, len(leads))
	existenceQueries := make([]data.ReminderReceiptQuery, 0, len(leads))
	for _, lead := range leads {
		if lead.OwnerUser == nil || *lead.OwnerUser == "" || lead.StatusChangedAt == nil || lead.UpdatedAt == "" {
			continue
		}
		sourceEventID := staleReminderSourceEventID(lead.ID, runDate)
		eligible = append(eligible, lead)
		existenceQueries = append(existenceQueries, data.NewReminderReceiptQuery().WhereSourceEventIDEqual(sourceEventID))
	}
	exists := make([]bool, len(existenceQueries))
	if len(existenceQueries) > 0 {
		exists, err = caps.ReminderReceipt.ExistsBatch(ctx, existenceQueries)
		if err != nil {
			return capabilities.SendStaleRemindersOutput{}, err
		}
	}
	creates := make([]schema.CreateReminderReceipt, 0, len(eligible))
	intents := make([]capabilities.SendStaleRemindersNotificationIntent, 0, len(eligible))
	for index, lead := range eligible {
		sourceEventID := staleReminderSourceEventID(lead.ID, runDate)
		owner, companyName := *lead.OwnerUser, lead.CompanyName
		intents = append(intents, capabilities.SendStaleRemindersNotificationIntent{
			EventType: "crm.lead_stale", SourceEventID: sourceEventID + ":" + input.RequestKey,
			RecipientUserIDs: []string{owner}, Surface: "business_workspace",
			SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: lead.UpdatedAt,
			DedupeKey: sourceEventID, GroupKey: string(lead.ID), Alert: true, OccurredAt: runDate,
			Variables: []capabilities.SendStaleRemindersNotificationVariable{{Key: "company_name", StringValue: &companyName}},
		})
		if exists[index] {
			continue
		}
		creates = append(creates, schema.CreateReminderReceipt{
			LeadID: schema.NewReminderReceiptLeadIDReference(lead.ID), RecipientUser: owner,
			ReminderDate: runDate, SourceEventID: sourceEventID,
		})
	}
	if len(creates) > 0 {
		if _, err = caps.ReminderReceipt.CreateBatch(ctx, creates); err != nil {
			return capabilities.SendStaleRemindersOutput{}, err
		}
	}
	_, err = caps.StaleScanRun.Create(ctx, schema.CreateStaleScanRun{
		RequestKey: input.RequestKey + ":" + caps.Execution.Principal().RequestID, RunDate: runDate,
		EligibleCount: int64(len(eligible)), CreatedCount: int64(len(creates)), ExecutedAt: time.Now().UTC(),
	})
	if err != nil {
		return capabilities.SendStaleRemindersOutput{}, err
	}
	if len(intents) > 0 {
		if _, err = caps.Notifications.DispatchBatch(ctx, intents); err != nil {
			return capabilities.SendStaleRemindersOutput{}, err
		}
	}
	return capabilities.SendStaleRemindersOutput{EligibleCount: int64(len(eligible)), CreatedCount: int64(len(creates))}, nil
}

func staleReminderSourceEventID(leadID schema.LeadID, runDate time.Time) string {
	return fmt.Sprintf("stale:%s:%s", leadID, runDate.Format(time.DateOnly))
}
