#!/usr/bin/env python3
"""Generic acceptance-harness core for Builder Skill deliveries.

Harness discipline: the agent writes ONLY per-case assertion functions on top of
this file — never its own session/HTTP/database/artifact plumbing. Workflow:
  1. After `project acceptance prepare` and Runtime startup, run the platform
     runner FIRST: `"$DOMAINRY_CLI" project acceptance run --json --project
     "$PROJECT_ROOT" --cases standard --results <results-file>`.
  2. Copy this file unchanged into <project>/.domainry/development/ (harness
     code never lives under backend/**).
  3. In a sibling file, write one assertion function per case whose durable
     result has disposition `needs_business_harness`; each performs real probes through the helpers here and returns
     typed observations, which this core seals into the exact artifact/evidence
     JSON shapes `project acceptance check` validates.
  4. Merge into the SAME results file the runner used (Harness.run_case does);
     never re-implement or overwrite a runner-recorded case. Then run
     `project acceptance check` against that file.
  5. After a model evolution (new denominator): run `project acceptance
     stale-report`, pass its JSON as Harness(..., stale_report=...) so the
     results file is rebound instead of rebuilt, and re-record ONLY
     pending_cases(stale_case_ids(<report>)) — never the full set.

SQLite uses Python stdlib. MySQL uses the core-owned strict Go-style Runtime
DSN adapter and lazy-loaded PyMySQL in autocommit mode so each acceptance query
reads the latest state committed by other Runtime connections; the agent passes
no connector and writes no DSN parser. PostgreSQL keeps the explicit advanced
DB-API 2 connector boundary.
The core owns all SQL dialect, cohort, snapshot, plan, redaction, and evidence
plumbing. Secrets from
acceptance-secrets.json (mode 0600) and DATABASE_DSN are never copied into
evidence or results; the recorder fail-closes on any leak.
"""

import copy
import contextlib
import hashlib
import ipaddress
import json
import math
import os
import re
import secrets as _random
import sqlite3
import time
import urllib.error
import urllib.parse
import urllib.request

# Contract identities pinned to internal/builder/backendacceptance (contract.go,
# artifact.go) and .../runner (runner.go, recorder.go, local.go). Do not edit.
DENOMINATOR_CONTRACT = "domainry-backend-acceptance-denominator-v1"
SEMANTIC_CONTRACT = "domainry-semantic-acceptance-contract-v1"
RESULTS_CONTRACT = "domainry-backend-acceptance-results-v2"
EVIDENCE_CONTRACT = "domainry-backend-acceptance-evidence-v1"
ARTIFACT_CONTRACT = "domainry-backend-acceptance-artifact-v1"
RUN_REPORT_CONTRACT = "domainry-backend-acceptance-run-v2"
STALE_REPORT_CONTRACT = "domainry-backend-acceptance-stale-report-v1"
PRODUCER = "domainry-runtime-acceptance-harness"
PRINCIPAL_CONTEXT_CONTRACT = "domainry-principal-context-v1"
ACCEPTANCE_SECRETS_CONTRACT = "domainry-acceptance-secrets-v1"
RUNTIME_PROCESS_CONTRACT = "domainry-managed-runtime-process-v3"
DATABASE_COHORT_CONTRACT = "domainry-managed-runtime-database-cohort-v1"

DENOMINATOR_RELATIVE = ".domainry/builder/acceptance/denominator.json"
RUNTIME_STATE_RELATIVE = ".domainry/builder/runtime/runtime-process.json"
SECRETS_RELATIVE = ".domainry/builder/runtime/acceptance-secrets.json"
DEFAULT_RESULTS_RELATIVE = "backend/tests/evidence/backend-acceptance-results.json"
DEFAULT_EVIDENCE_ROOT = ".domainry/development/acceptance-evidence"
ISOLATED_EVIDENCE_BASE = DEFAULT_EVIDENCE_ROOT + "/by-results"

# Platform development default credential (managed development Runtime only);
# a successful bootstrap immediately rotates it and stores the rotation in the
# 0600 secrets file. Never print it, or any rotated value, into evidence.
DEV_DEFAULT_PASSWORD = "Domainry@2026"

# kind -> allowed captured_from values (first entry is the default), mirroring
# the validator's allowedCapture map in backendacceptance/artifact.go.
CAPTURED_FROM = {
    "http_exchange": ["runtime_http"], "sse_transcript": ["runtime_http"], "durable_refetch": ["runtime_http"],
    "runtime_restart": ["runtime_process"], "worker_terminal": ["runtime_worker"],
